-- bpu_ports.lua: machine port flags, website export <-> game config byte order. Pure Lua 5.4, no game globals.
-- Data: bpu_port_data.lua (generated by tooling/gen_port_order.py). Units: half cells, origin = machine centre, y down.
-- Rotation step = clockwise quarter turn in the y-down view: (x, y) -> (-y, x).
-- Lua lists are 1-based (flags[i] = game byte i-1). Pm.index returns the 0-based game byte index.
--
-- API:  Pm.verified(class) -> bool
--       Pm.game_cells(class, rot) -> { {x,y}, ... } (game order)           UNVERIFIED for rot ~= 0 (see below)
--       Pm.index(class, port, rot) -> 0-based game index | nil, err      port = {face=, index=} (site) or {x=, y=} (cell at rot 0)
--       Pm.site_to_game(class, rot, site_ports) -> { bool, ... } | nil, err   site_ports = { {face=, index=, enabled=}, ... } (nil = all on)
--       Pm.game_to_site(class, rot, flags) -> { {face=, index=, enabled=}, ... } | nil, err
--       Pm.assume_rot = false  -- plan applies port diffs on rot ~= 0 only when true

local DATA = require("bpu_port_data")

local Pm = {}
Pm.assume_rot = false

local function rot_cell(x, y, rot)
    for _ = 1, (rot or 0) % 4 do x, y = -y, x end
    return x, y
end

function Pm.verified(class)
    local d = DATA[class]
    return d ~= nil and d.verified == true and d.site ~= nil
end

-- UNVERIFIED for rot ~= 0: needs bp_ports on a rotated machine. Assumed: game list = definition list with each
-- cell rotated, same index. If the game re-sorts rotated lists, change only this function.
function Pm.game_cells(class, rot)
    local d = DATA[class]
    if not d then return nil, "no port data for " .. tostring(class) end
    local out = {}
    for i, c in ipairs(d.cells) do
        local x, y = rot_cell(c[1], c[2], rot)
        out[i] = { x, y }
    end
    return out
end

function Pm.index(class, port, rot)
    local d = DATA[class]
    if not d then return nil, "no port data for " .. tostring(class) end
    local x, y = port.x, port.y
    if not port.face and x == nil then return nil, "bad port on " .. class end
    if port.face then
        local hit
        for _, e in ipairs(d.site or {}) do
            if e.face == port.face and e.index == port.index then hit = e break end
        end
        if not hit then return nil, "unknown port " .. tostring(port.face) .. tostring(port.index) .. " on " .. class end
        x, y = hit.x, hit.y
    end
    x, y = rot_cell(x, y, rot)
    local cells = Pm.game_cells(class, rot)
    for i, c in ipairs(cells) do
        if c[1] == x and c[2] == y then return i - 1 end
    end
    return nil, "no game port at (" .. x .. "," .. y .. ") on " .. class
end

function Pm.site_to_game(class, rot, site_ports)
    if not Pm.verified(class) then return nil, "ports not verified for " .. tostring(class) end
    local cells = Pm.game_cells(class, rot)
    local out = {}
    for i = 1, #cells do out[i] = true end
    for _, sp in ipairs(site_ports or {}) do
        local i, why = Pm.index(class, sp, rot)
        if not i then return nil, why end
        out[i + 1] = sp.enabled ~= false
    end
    return out
end

function Pm.game_to_site(class, rot, flags)
    if not Pm.verified(class) then return nil, "ports not verified for " .. tostring(class) end
    local cells = Pm.game_cells(class, rot)
    if #flags ~= #cells then return nil, "flag count " .. #flags .. " ~= " .. #cells .. " for " .. class end
    local out = {}
    for k, e in ipairs(DATA[class].site) do
        local i, why = Pm.index(class, { face = e.face, index = e.index }, rot)
        if not i then return nil, why end
        out[k] = { face = e.face, index = e.index, enabled = flags[i + 1] == true }
    end
    return out
end

return Pm
